def flatten_dict(nested: dict, sep: str = '.') -> dict:
    if not isinstance(nested, dict):
        raise TypeError('Input must be a dict')
    result = {}
    def _recurse(curr, prefix):
        if isinstance(curr, dict):
            if not curr and prefix:
                result[prefix] = {}
            else:
                for k, v in curr.items():
                    new_key = f'{prefix}{sep}{k}' if prefix else str(k)
                    _recurse(v, new_key)
        elif isinstance(curr, list):
            if not curr and prefix:
                result[prefix] = []
            else:
                for idx, item in enumerate(curr):
                    new_key = f'{prefix}{sep}{idx}' if prefix else str(idx)
                    _recurse(item, new_key)
        else:
            result[prefix] = curr
    _recurse(nested, '')
    return result

def make_handlers(names, base_config=None):
    cfg = dict(base_config) if base_config is not None else {}
    for name in names:
        cfg[name] = True
    handlers = []
    cfg_len = len(cfg)
    for name in names:
        handlers.append((lambda n=name, l=cfg_len: f'{n}:{l}'))
    return handlers

