CLIENT_DISCOUNTS = {
    'vip': 0.20,
    'premium': 0.10,
    'standard': 0.00
}
COUPON_DISCOUNTS = {
    'SAVE10': 0.10,
    'SAVE5': 0.05,
    '': 0.00
}

def calculate_order_price(order: dict) -> float:
    subtotal = float(order.get('subtotal', 0.0))
    if subtotal < 0:
        raise ValueError('Subtotal cannot be negative')
    tier = order.get('client_tier', 'standard')
    if tier not in CLIENT_DISCOUNTS:
        raise ValueError(f'Unknown client tier: {tier}')
    coupon = order.get('coupon', '')
    items_count = order.get('items_count', 1)

    discount = CLIENT_DISCOUNTS[tier] + COUPON_DISCOUNTS.get(coupon, 0.0)
    if items_count >= 10:
        discount += 0.05

    effective_discount = min(discount, 0.50)
    final_price = subtotal * (1.0 - effective_discount)
    return round(final_price, 2)

import asyncio

async def fetch_all_with_concurrency(items: list, fetch_fn, max_concurrency: int = 3, timeout_per_item: float = 2.0) -> list[dict]:
    sem = asyncio.Semaphore(max_concurrency)
    async def _process_item(item):
        async with sem:
            try:
                res = await asyncio.wait_for(fetch_fn(item), timeout=timeout_per_item)
                return {'item': item, 'status': 'success', 'result': res}
            except Exception as e:
                return {'item': item, 'status': 'error', 'error': str(e)}
    tasks = [_process_item(item) for item in items]
    return await asyncio.gather(*tasks)

